    for (let x = -20; x <= A.W + 40; x += 40) ctx.lineTo(x, g + i * 75 + Math.sin((x + off) / 120 + i) * 10);
    ctx.lineTo(A.W + 40, 1150); ctx.lineTo(-20, 1150); ctx.closePath(); ctx.fill();
  }
  A.line([[540, g + 4], [505, g + 90], [570, g + 180], [520, g + 270], [580, g + 380]], { stroke: A.accent, lw: 9, glow: 30, progress: A.p(mv, 0.7) });
  const s = A.pop(0.15);
  A.with(() => {
    A.circle(540, g - 200, 36, { fill: '#fff' });
    A.line([[540, g - 158], [540, g - 72]], { stroke: '#fff', lw: 18 });
    A.line([[540, g - 72], [508, g]], { stroke: '#fff', lw: 18 });
    A.line([[540, g - 72], [572, g]], { stroke: '#fff', lw: 18 });
    A.line([[540, g - 135], [492, g - 88 + Math.sin(t * 6) * 6]], { stroke: '#fff', lw: 15 });
    A.line([[540, g - 135], [588, g - 88 - Math.sin(t * 6) * 6]], { stroke: '#fff', lw: 15 });
  }, { x: 540, y: g, scale: s * 1.5 });
  A.arrow(800, g - 150, 620, g - 20, { progress: A.p(pies, 0.4), color: A.accent, lw: 9 });
  A.label('TUS PIES', 820, g - 160, { scale: A.pop(pies), size: 40 });
}, { shake: sh });
const pm = A.p(mv, 0.5);
for (let i = 0; i < 3; i++) {
  const y = 1420 + i * 110, d = (t * 140 + i * 50) % 140;
  A.arrow(200 + d, y, 380 + d, y, { progress: pm, color: i % 2 ? '#fff' : A.accent, lw: 10, alpha: 0.9 });
  A.arrow(880 - d, y + 50, 700 - d, y + 50, { progress: pm, color: i % 2 ? A.accent : '#fff', lw: 10, alpha: 0.9 });
}

A.bg('#06202a', '#03080c');
const cx = 540, cy = 760, R = 310 * A.pop(0, 0.7);
const placas = A.k('placas', 1.5), cm = A.k('centimetros', 3), unas = A.k('unas', 5);
A.circle(cx, cy, R, { fill: '#0f4c63', glow: 60, glowColor: A.accent });
if (R > 1) {
  ctx.save(); ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.clip();
  const r = A.rand(3);
  for (let i = 0; i < 8; i++) {
    const bx = ((r() * 1000 + t * 45) % 1000) - 500 + cx, by = cy - 250 + r() * 500, rr = 50 + r() * 80;
    A.circle(bx, by, rr, { fill: '#2f8a57' }); A.circle(bx + rr * 0.7, by + rr * 0.4, rr * 0.7, { fill: '#2f8a57' });
  }
  const bordes = [
    [[cx - 320, cy - 120], [cx - 130, cy - 60], [cx - 40, cy - 180], [cx + 120, cy - 120], [cx + 320, cy - 200]],
    [[cx - 320, cy + 90], [cx - 90, cy + 140], [cx + 30, cy + 40], [cx + 200, cy + 120], [cx + 320, cy + 60]],
    [[cx - 40, cy - 180], [cx - 10, cy - 20], [cx + 30, cy + 40], [cx + 10, cy + 320]],
