  bordes.forEach((b, i) => A.line(b, { stroke: A.accent, lw: 10, glow: 25, progress: A.p(placas + i * 0.25, 0.8) }));
  const sombra = ctx.createRadialGradient(cx - 120, cy - 140, 40, cx, cy, R);
  sombra.addColorStop(0, 'rgba(255,255,255,0.12)'); sombra.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = sombra; ctx.fillRect(cx - R, cy - R, 2 * R, 2 * R);
  ctx.restore();
}
A.circle(cx, cy, R, { stroke: 'rgba(255,255,255,0.35)', lw: 4 });
const pa = A.p(placas + 0.9, 0.5);
A.arrow(cx - 230, cy - 20, cx - 90 + Math.sin(t * 3) * 12, cy - 20, { progress: pa, color: '#fff', lw: 12 });
A.arrow(cx + 230, cy + 60, cx + 90 - Math.sin(t * 3) * 12, cy + 60, { progress: pa, color: '#fff', lw: 12 });
const pr = A.p(cm, 1.4), al = A.p(cm, 0.3);
A.rect(170, 1400, 740, 70, { r: 14, stroke: 'rgba(255,255,255,0.6)', lw: 4, alpha: al });
A.rect(170, 1400, Math.max(740 * pr, 1), 70, { r: 14, fill: A.accent, alpha: 0.95 * al });
for (let i = 0; i <= 10; i++) A.line([[170 + i * 74, 1478], [170 + i * 74, 1478 + (i % 5 ? 18 : 34)]], { stroke: '#fff', lw: 4, alpha: al });
A.text('≈ ' + A.counter(0, 5, pr) + ' cm / año', 540, 1575, { size: 66, alpha: al });
A.label('= LO QUE CRECEN TUS UÑAS', 540, 1680, { scale: A.pop(unas), size: 42 });

A.bg('#2a1206', '#080403');
const tr = A.k('traban', 1), fr = A.k('friccion', 1.8), pre = A.k('presion', 2.6), an = A.k('anos', 3.6), sig = A.k('siglos', 4.6);
const jag = []; for (let i = 0; i <= 8; i++) jag.push([540 + (i % 2 ? 28 : -28), 470 + i * 75]);
const dx = (1 - A.p(0, 1.0)) * 140;
const tension = A.p(pre, Math.max(A.dur - pre, 0.5), 'linear');
const vib = tension * 6 * Math.sin(t * 55);
function placa(x0, color, sx) {
  ctx.save(); ctx.translate(sx, 0); ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(x0, 470);
  jag.forEach(p => ctx.lineTo(p[0], p[1])); ctx.lineTo(x0, 1070); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.25)'; ctx.lineWidth = 3;
  for (let y = 540; y < 1070; y += 90) { ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(540, y + 10); ctx.stroke(); }
  ctx.restore();
}
placa(70, '#9a5f2c', -dx + vib);
placa(1010, '#6e411d', dx - vib);
const pf = A.p(tr, 0.5);
A.arrow(90, 640, 330, 640, { progress: pf, color: '#fff', lw: 16, head: 50 });
A.arrow(990, 900, 750, 900, { progress: pf, color: '#fff', lw: 16, head: 50 });
jag.forEach((p, i) => { const s = A.pop(fr + i * 0.07, 0.3); A.circle(p[0], p[1], 16 * s, { fill: A.accent, glow: 30 }); });
A.label('FRICCIÓN', 540, 1110, { scale: A.pop(fr), size: 40 });
// medidor de presión (zona inferior)
const col = `hsl(${A.lerp(50, 0, tension)}, 95%, 55%)`;
A.text('PRESIÓN', 170, 1400, { size: 46, align: 'left', alpha: A.p(pre, 0.3) });
A.text(Math.round(tension * 100) + '%', 910, 1400, { size: 46, align: 'right', color: col, alpha: A.p(pre, 0.3) });
A.rect(170, 1440, 740, 60, { r: 30, stroke: 'rgba(255,255,255,0.5)', lw: 4, alpha: A.p(pre, 0.3) });
if (tension > 0.02) A.rect(170, 1440, 740 * tension, 60, { r: 30, fill: col, glow: 30 * tension });
const ay = A.p(an, Math.max(A.dur - an, 0.5), 'inCubic');
A.text(A.counter(0, t > sig ? 300 : 80, ay) + ' AÑOS', 540, 1630, { size: 84, color: A.accent, alpha: A.p(an, 0.3), scale: 1 });

A.bg('#2a0707', '#070202');
const rompe = A.k('rompe', 1.6), sismo = A.k('sismo', 2.8), energia = A.k('energia', 3.4), seg = A.k('segundos', A.dur - 0.6);
