const pre = t < rompe ? A.p(0, rompe, 'inCubic') : 0;
const slip = t >= rompe ? A.p(rompe, 0.25, 'outBack') * 70 : 0;
const sh = t < rompe ? pre * 10 : 26 * (1 - A.p(rompe, 1.6, 'linear'));
A.with(() => {
  function placa(x0, color, dy, sx) {
    ctx.save(); ctx.translate(sx, dy); ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(x0, 470);
    jag.forEach(p => ctx.lineTo(p[0], p[1])); ctx.lineTo(x0, 1070); ctx.closePath(); ctx.fill(); ctx.restore();
  }
  const v = pre * 7 * Math.sin(t * 70);
  placa(70, '#9a5f2c', -slip, v);
  placa(1010, '#6e411d', slip, -v);
  if (t >= rompe) {
    A.line(jag, { stroke: '#fff', lw: 10, glow: 50, glowColor: A.accent, alpha: 1 - A.p(rompe + 0.6, 1.2) * 0.6 });
    A.particles(40, 9, (i, r) => {
      const a = r() * Math.PI * 2, v = 300 + r() * 700, tt = t - rompe, y0 = 500 + r() * 560;
      const x = 540 + Math.cos(a) * v * tt, y = y0 + Math.sin(a) * v * tt + 900 * tt * tt;
      A.rect(x, y, 14 + r() * 18, 14 + r() * 18, { fill: r() > 0.5 ? '#c98a4a' : A.accent, alpha: 1 - A.p(rompe, 1.5, 'linear') });
    });
  }
}, { shake: sh });
A.rings(540, 770, rompe, { count: 5, speed: 900, gap: 0.18, maxR: 1100, lw: 14, glow: 30 });
A.flash(rompe, 0.3, 0.85);
A.with(() => A.text('¡CRACK!', 540, 770, { size: 150, weight: 900, color: '#fff', stroke: '#000', strokeWidth: 16, alpha: 1 - A.p(rompe + 0.8, 0.4) }),
  { x: 540, y: 770, scale: A.pop(rompe, 0.35), rot: -0.08 });
A.label('SISMO', 540, 1110, { scale: A.pop(sismo), size: 48 });
const pe = A.p(energia, 0.4), drain = A.p(seg - 0.3, 0.6, 'inCubic');
A.text('ENERGÍA', 170, 1410, { size: 44, align: 'left', alpha: pe });
A.rect(170, 1450, 740, 70, { r: 35, stroke: 'rgba(255,255,255,0.5)', lw: 4, alpha: pe });
A.rect(170, 1450, Math.max(740 * (1 - drain), 1), 70, { r: 35, fill: A.accent, glow: 30, alpha: pe });
A.text('AÑOS', 260, 1610, { size: 60, alpha: pe });
A.arrow(380, 1610, 610, 1610, { progress: A.p(energia + 0.5, 0.6), color: '#fff', lw: 10 });
A.text('SEGUNDOS', 800, 1610, { size: 60, color: A.accent, alpha: A.p(seg - 0.3, 0.3) });

A.bg('#1d1a06', '#050402');
const sup = 640, hip = A.k('hipocentro', 2), epi = A.k('epicentro', 4.2), rompe = A.k('rompe', 1);
const r = A.rand(5);
for (let i = 0; i < 9; i++) {
  const w = 60 + r() * 50, h = 80 + r() * 150, x = 70 + i * 106;
  const s = A.p(i * 0.06, 0.5, 'outBack');
  A.rect(x, sup - h * s, w, h * s, { fill: i % 3 ? '#3b4252' : '#4c566a' });
  for (let k = 0; k < 4; k++) A.rect(x + 12, sup - h * s + 15 + k * 30, 14, 14, { fill: '#ffe08a', alpha: s * (r() > 0.4 ? 0.9 : 0.2) });
}
const g = ctx.createLinearGradient(0, sup, 0, 1130); g.addColorStop(0, '#6b4c22'); g.addColorStop(1, '#24190b');
ctx.fillStyle = g; ctx.fillRect(0, sup, A.W, 1130 - sup);
for (let i = 1; i < 6; i++) A.line([[0, sup + i * 85], [A.W, sup + i * 85 + 20 * Math.sin(i)]], { stroke: 'rgba(0,0,0,0.25)', lw: 4 });
A.line([[0, sup], [A.W, sup]], { stroke: '#fff', lw: 6 });
const hx = 540, hy = 1010;
A.rings(hx, hy, rompe, { count: 3, speed: 260, gap: 0.6, maxR: 380, lw: 6 });
const sh = A.pop(hip);
A.with(() => {
  ctx.save(); ctx.fillStyle = A.accent; ctx.shadowColor = A.accent; ctx.shadowBlur = 40; ctx.beginPath();
  for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? 24 : 58; ctx.lineTo(hx + Math.cos(a) * rr, hy + Math.sin(a) * rr); }
  ctx.closePath(); ctx.fill(); ctx.restore();
}, { x: hx, y: hy, scale: Math.max(sh, t > rompe ? 0.5 : 0) * (1 + 0.08 * Math.sin(t * 8)) });
A.label('HIPOCENTRO', 540, 1420, { scale: A.pop(hip), size: 54 });
A.text('donde se rompe la roca', 540, 1510, { size: 40, weight: 600, alpha: A.p(hip + 0.3, 0.4) });
A.arrow(540, 1360, 540, 1090, { progress: A.p(hip + 0.2, 0.4), color: A.accent, lw: 8 });
A.line([[hx, hy - 60], [hx, sup]], { stroke: '#fff', lw: 6, dash: [18, 16], progress: A.p(epi - 0.4, 0.5) });
const pe = A.pop(epi);
A.with(() => {
  A.circle(540, sup - 120, 46, { fill: '#ff3d3d', glow: 40 });
  ctx.fillStyle = '#ff3d3d'; ctx.beginPath(); ctx.moveTo(500, sup - 100); ctx.lineTo(580, sup - 100); ctx.lineTo(540, sup - 10); ctx.closePath(); ctx.fill();
  A.circle(540, sup - 120, 18, { fill: '#fff' });
}, { x: 540, y: sup, scale: pe });
A.rings(540, sup, epi, { count: 2, speed: 300, gap: 0.5, maxR: 260, lw: 6, color: '#ff3d3d' });
A.label('EPICENTRO', 540, 1640, { scale: A.pop(epi + 0.1), size: 54, bg: '#ff3d3d', color: '#fff' });
A.text('justo encima, en la superficie', 540, 1725, { size: 38, weight: 600, alpha: A.p(epi + 0.4, 0.4) });

A.bg('#0a1f05', '#030602');
const salen = A.k('ondas', 0.6), tP = A.k('ondas', 1.6, 2) + 0.2, tS = A.k('luego', 3.4) + 0.3, sac = A.k('sacuden', A.dur - 0.8);
const sup = 520, sx = 540, sy = 1030;
const g = ctx.createLinearGradient(0, sup, 0, 1120); g.addColorStop(0, '#4a3418'); g.addColorStop(1, '#1e150a');
ctx.fillStyle = g; ctx.fillRect(0, sup, A.W, 600);
A.line([[0, sup], [A.W, sup]], { stroke: '#fff', lw: 5 });
const shake = t > sac ? 8 : 0;
A.with(() => { for (let i = 0; i < 6; i++) A.rect(120 + i * 150, sup - 110 - (i % 3) * 40, 90, 110 + (i % 3) * 40, { fill: '#3b4252' }); }, { shake: t > tS + 0.8 ? 10 : 0 });
A.circle(sx, sy, 22, { fill: '#fff', glow: 30 });
ctx.save(); ctx.beginPath(); ctx.rect(0, 400, A.W, 720); ctx.clip();
A.rings(sx, sy, tP, { count: 6, speed: 900, gap: 0.18, maxR: 800, lw: 5, color: A.accent, glow: 15 });
A.rings(sx, sy, tS, { count: 5, speed: 420, gap: 0.3, maxR: 800, lw: 16, color: '#ff4d4d', glow: 25 });
