A.label('ONDAS P · RÁPIDAS', 300, 1100, { scale: A.pop(tP), size: 36 });
A.label('ONDAS S · FUERTES', 780, 1100, { scale: A.pop(tS), size: 36, bg: '#ff4d4d', color: '#fff' });
// sismógrafo
const x0 = 110, x1 = 970, yc = 1560, pen = x1;
A.rect(80, 1360, 920, 380, { r: 24, fill: '#f4f1e8', alpha: A.p(salen, 0.4) });
if (t > salen) {
  ctx.save(); ctx.beginPath(); ctx.rect(90, 1370, 900, 360); ctx.clip();
  for (let x = x0; x < x1; x += 120) A.line([[x - (t * 200) % 120 + 120, 1370], [x - (t * 200) % 120 + 120, 1730]], { stroke: 'rgba(0,0,0,0.08)', lw: 2 });
  const pts = [];
  for (let x = x0; x <= pen; x += 3) {
    const tau = t - (pen - x) / 200;
    let a = 4;
    if (tau > tP) a = 35; if (tau > tS) a = 150 * (tau > sac ? 1.15 : 1);
    pts.push([x, yc + a * Math.sin(tau * 45) * Math.sin(tau * 13 + x * 0.01)]);
  }
  A.line(pts, { stroke: '#111', lw: 4 });
  ctx.restore();
  A.circle(pts[pts.length - 1][0], pts[pts.length - 1][1], 12, { fill: '#ff3d3d' });
}
A.text('SISMÓGRAFO', 540, 1395, { size: 30, color: '#555', alpha: A.p(salen, 0.4) });

A.bg('#2a1406', '#070302');
const al = A.k('alertas', 0.8), sen = A.k('sensores', 2.2), det = A.k('detectan', 2.6), avi = A.k('aviso', 4.6), rap = A.k('rapido', 5.4);
const ex = 170, ey = 800, cx = 880;
A.rect(60, 460, 960, 640, { r: 30, fill: 'rgba(255,255,255,0.04)', stroke: 'rgba(255,255,255,0.15)', lw: 3 });
for (let i = 0; i < 5; i++) A.rect(790 + i * 42, 800 - 60 - (i % 2) * 70, 34, 60 + (i % 2) * 70 + 120, { fill: '#4c566a' });
A.text('CIUDAD', cx, 1050, { size: 34, color: '#bbb' });
ctx.save(); ctx.beginPath(); ctx.rect(60, 460, 960, 640); ctx.clip();
A.rings(ex, ey, 0, { count: 6, speed: 130, gap: 0.9, maxR: 900, lw: 10, color: '#ff4d4d', alpha: 0.9 });
