  A.line([[tx - 30, ty + 90], [tx, ty], [tx + 30, ty + 90]], { stroke: '#fff', lw: 8 });
  A.line([[tx - 18, ty + 50], [tx + 18, ty + 50]], { stroke: '#fff', lw: 6 });
  A.circle(tx, ty, 14, { fill: A.accent, glow: 30 });
  for (let i = 1; i <= 2; i++) A.circle(tx, ty, 26 * i + (t * 40) % 26, { stroke: A.accent, lw: 4, alpha: 0.6 });
}, { x: tx, y: ty + 90, scale: ps });
A.label('SENSOR', tx, ty - 70, { scale: A.pop(sen + 0.1), size: 34 });
const pz = A.p(det, 0.5, 'linear');
const bolt = [[tx, ty], [450, 640], [520, 700], [610, 620], [700, 690], [830, 640]];
A.line(bolt, { stroke: A.accent, lw: 10, glow: 40, progress: pz, dash: [26, 14] });
A.flash(det + 0.5, 0.2, 0.35);
// teléfono
const pp = A.pop(det + 0.4), parp = Math.sin(t * 14) > 0;
A.with(() => {
  A.rect(390, 1340, 300, 420, { r: 40, fill: '#111', stroke: '#888', lw: 6 });
  A.rect(410, 1380, 260, 340, { r: 20, fill: t > det + 0.5 && parp ? '#ff2d2d' : '#3a0d0d' });
  ctx.save(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.moveTo(540, 1430); ctx.lineTo(600, 1530); ctx.lineTo(480, 1530); ctx.closePath(); ctx.fill(); ctx.restore();
  A.text('!', 540, 1498, { size: 60, color: '#ff2d2d', weight: 900 });
  A.text('ALERTA', 540, 1590, { size: 44, weight: 900 });
  A.text('SÍSMICA', 540, 1645, { size: 44, weight: 900 });
}, { x: 540, y: 1550, scale: pp });
// carrera aviso vs ondas
const pr = A.p(avi, 0.4);
A.text('AVISO', 90, 1390, { size: 34, align: 'left', alpha: pr }); A.rect(90, 1420, Math.max(250 * A.p(avi, 0.5), 1), 30, { r: 15, fill: A.accent, alpha: pr });
A.text('ONDAS', 90, 1500, { size: 34, align: 'left', alpha: pr }); A.rect(90, 1530, Math.max(250 * A.p(avi, 4, 'linear'), 1), 30, { r: 15, fill: '#ff4d4d', alpha: pr });
A.label('¡GANA EL AVISO!', 870, 1450, { scale: A.pop(rap), size: 32 });

A.bg('#04202a', '#020709');
