  ctx.restore();
  A.text('M5', 130, 1045, { size: 36, alpha: g5 > 0 ? 1 : 0 });
  A.text('M6', 290, 1100 - 2 * r6 - 30, { size: 40, alpha: g6 > 0 ? 1 : 0 });
